fn not_equal(a: Vec<i8>, b: Vec<i8>) -> Vec<bool> {
    // Since both arrays have the same length, we can iterate over pairs of elements,
    // comparing the values and producing a boolean vector where each element indicates
    // whether the corresponding elements differ.
    
    // Using iterator zip and map to generate the boolean vector.
    a.into_iter()
     .zip(b.into_iter())
     .map(|(x, y)| x != y)
     .collect()
}